<script setup>
import {ref,onMounted,onBeforeUnmount,watch} from 'vue';
import * as L from 'leaflet';import 'leaflet/dist/leaflet.css';
const props=defineProps({node:Object,rows:Array,theme:Object,interactive:Boolean,playing:Boolean});const emit=defineEmits(['action']);
const host=ref(),layer=ref(props.node.props.tileLayer||'satellite'),selected=ref(null),failed=ref(false),ready=ref(false);let map,tiles,overlays,observer,errors=0,disposed=false;
const sources={satellite:{url:'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',attribution:'Imagery © Esri, Maxar, Earthstar Geographics, GIS User Community',maxNativeZoom:19},street:{url:'https://tile.openstreetmap.org/{z}/{x}/{y}.png',attribution:'© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap contributors</a>',maxNativeZoom:19}};
function setLayer(value){layer.value=value;failed.value=false;errors=0;if(!map)return;tiles?.remove();const source=sources[value]||sources.satellite;tiles=L.tileLayer(source.url,{attribution:source.attribution,maxZoom:20,maxNativeZoom:source.maxNativeZoom,keepBuffer:1,updateWhenIdle:true,crossOrigin:true});tiles.on('tileerror',()=>{if(++errors>=3)failed.value=true;});tiles.on('tileload',()=>{failed.value=false;});tiles.addTo(map);}
function reset(){selected.value=null;map?.flyTo([props.node.props.lat,props.node.props.lng],props.node.props.zoom,{duration:.8});}
function updateOverlays(){if(!map)return;overlays?.remove();overlays=L.layerGroup().addTo(map);if(props.node.props.gisOverlays===false)return;const {lat,lng}=props.node.props;
 const points=(props.rows||props.node.data?.rows)?.filter(r=>Number.isFinite(Number(r.lat))&&Number.isFinite(Number(r.lng)))||[];
 for(const [i,row] of points.slice(0,200).entries()){
  const a=Number(row.lat),b=Number(row.lng),color=row.status==='待复核'?'#f3bf70':props.theme.accent;
  if(Math.abs(a)>85||Math.abs(b)>180)continue;const button=document.createElement('button');button.className='aw-gis-marker';button.type='button';button.style.setProperty('--marker-color',color);button.setAttribute('aria-label','查看 '+(row.name||'监测点')+' 详情');const marker=L.marker([a,b],{icon:L.divIcon({html:button,className:'aw-gis-marker-host',iconSize:[20,20],iconAnchor:[10,10]}),keyboard:false}).addTo(overlays);button.addEventListener('click',e=>{e.stopPropagation();selected.value={...row,index:i+1};emit('action','click',row);});
  const label=document.createElement('span');label.textContent=row.name||'监测点';marker.bindTooltip(label,{direction:'top',offset:[0,-7],permanent:true,className:'aw-gis-label'});
  marker.on('click',()=>{selected.value={...row,index:i+1};emit('action','click',row);});
  if(row.radius)L.circle([a,b],{radius:Math.min(3000,Math.max(20,Number(row.radius)||100)),color,weight:1,dashArray:'5 7',fillColor:color,fillOpacity:.08,interactive:false}).addTo(overlays);
 }
}
function interactivity(){if(!map)return;for(const method of ['dragging','scrollWheelZoom','doubleClickZoom','touchZoom','boxZoom','keyboard'])map[method]?.[props.interactive?'enable':'disable']();}
onMounted(()=>{if(disposed)return;map=L.map(host.value,{center:[props.node.props.lat,props.node.props.lng],zoom:props.node.props.zoom,zoomControl:false,attributionControl:true,preferCanvas:true,zoomAnimation:!matchMedia('(prefers-reduced-motion: reduce)').matches});map.attributionControl.setPrefix('<a href="https://leafletjs.com" target="_blank" rel="noopener">Leaflet</a>');setLayer(layer.value);updateOverlays();interactivity();observer=new ResizeObserver(()=>map?.invalidateSize({pan:false}));observer.observe(host.value);ready.value=true;});
watch(()=>props.node.props.tileLayer,setLayer);watch(()=>[props.node.props.lat,props.node.props.lng,props.node.props.zoom],()=>{reset();updateOverlays();});watch(()=>[props.rows,props.node.data.rows,props.node.props.gisOverlays,props.theme.accent],updateOverlays,{deep:true});watch(()=>props.interactive,interactivity);
onBeforeUnmount(()=>{disposed=true;observer?.disconnect();map?.remove();map=null;});
</script>
<template><section class="aw-leaflet-scene" :data-map-ready="ready" aria-label="卫星 GIS 地图"><div ref="host" class="aw-leaflet-host"></div><div class="aw-gis-heading"><small>GEOSPATIAL INTELLIGENCE</small><strong>{{node.props.sceneTitle||'空间监测 · 卫星视图'}}</strong><span>WGS 84 · 实时底图 / 演示监测数据</span></div><nav v-if="interactive" class="aw-gis-layers" aria-label="GIS 底图"><button :aria-pressed="layer==='satellite'" @click.stop="setLayer('satellite')">卫星影像</button><button :aria-pressed="layer==='street'" @click.stop="setLayer('street')">OSM 街道</button></nav><div v-if="interactive" class="aw-gis-zoom"><button aria-label="放大地图" @click.stop="map?.zoomIn()">＋</button><button aria-label="缩小地图" @click.stop="map?.zoomOut()">−</button><button aria-label="复位地图" @click.stop="reset">⌖</button></div><div v-if="failed" class="aw-gis-offline" role="status">底图暂时无法连接 <button @click="setLayer(layer)">重新加载</button></div><aside v-if="selected" class="aw-gis-detail"><button aria-label="关闭 GIS 详情" @click="selected=null">×</button><small>SENSOR / {{String(selected.index).padStart(2,'0')}}</small><strong>{{selected.name}}</strong><p>{{selected.status||'运行正常'}} · 演示数据</p><dl><div><dt>水温</dt><dd>{{selected.value}}<em> °C</em></dd></div><div><dt>溶解氧</dt><dd>{{selected.oxygen||'6.8'}}<em> mg/L</em></dd></div></dl><span>{{Number(selected.lat).toFixed(4)}}° N / {{Number(selected.lng).toFixed(4)}}° E</span></aside><div class="aw-gis-key"><i></i> 在线监测点 <b></b> 感知覆盖范围 · 示意</div></section></template>
<style>
.aw-leaflet-scene{position:relative;width:100%;height:100%;overflow:hidden;background:#08191e;border:1px solid #4dceba38}.aw-leaflet-host{position:absolute;inset:0;z-index:0;background:#0d2029}.aw-leaflet-scene .leaflet-tile-pane{filter:saturate(.72) brightness(.79)}.aw-leaflet-scene .leaflet-control-attribution{background:#071722e8!important;color:#9badb7!important;font-size:9px;max-width:100%;padding:3px 7px}.aw-leaflet-scene .leaflet-control-attribution a{color:#badadf}.aw-gis-heading{position:absolute;left:26px;top:24px;display:grid;gap:8px;pointer-events:none;z-index:401;text-shadow:0 1px 8px #000}.aw-gis-heading small{font-size:10px;letter-spacing:4px;color:#59e0d4}.aw-gis-heading strong{font-size:22px;color:#e2f3ef;font-weight:500}.aw-gis-heading span{font-size:10px;color:#a0c2c7}.aw-gis-layers{position:absolute;right:18px;top:22px;display:flex;z-index:402;border:1px solid #45cbbb4d;background:#061923e8}.aw-gis-layers button{border:0;border-right:1px solid #45cbbb33;background:none;color:#97b6bd;font-size:11px;padding:10px 14px;cursor:pointer}.aw-gis-layers button[aria-pressed=true]{color:#051c24;background:#59e0d4}.aw-gis-zoom{position:absolute;right:18px;top:84px;display:grid;z-index:402;background:#071d29e8;border:1px solid #45cbbb44}.aw-gis-zoom button{background:none;border:0;border-bottom:1px solid #45cbbb22;color:#acd9d4;width:34px;height:34px;font-size:19px;cursor:pointer}.aw-gis-label.leaflet-tooltip{background:#051e2bdc;color:#d4f3eb;border:1px solid #52d5c67a;border-radius:2px;box-shadow:none;font-size:11px;padding:5px 9px}.aw-gis-label.leaflet-tooltip:before{border-top-color:#52d5c67a}.aw-gis-key{position:absolute;bottom:35px;right:20px;z-index:401;color:#bed5d9;background:#051923e3;padding:9px 12px;font-size:10px}.aw-gis-key i{display:inline-block;width:6px;height:6px;border-radius:50%;background:#63ebca;margin-right:6px}.aw-gis-key b{display:inline-block;width:9px;height:9px;border:1px dashed #63ebca;margin:0 5px 0 14px}.aw-gis-detail{position:absolute;bottom:38px;left:22px;z-index:403;background:#071c29f5;border-left:2px solid #6ce5c0;padding:20px;width:280px;color:#d2e9e7;box-shadow:0 8px 30px #0004}.aw-gis-detail>button{position:absolute;right:12px;top:7px;background:none;border:0;color:#9db9bf;font-size:22px;cursor:pointer}.aw-gis-detail small{display:block;color:#6ce5c0;letter-spacing:2px;font-size:9px;margin-bottom:10px}.aw-gis-detail strong{font-size:17px;font-weight:500}.aw-gis-detail p,.aw-gis-detail>span{font-size:10px;color:#7fa4af}.aw-gis-detail dl{display:flex;gap:35px;margin:18px 0}.aw-gis-detail dt{color:#7297a3;font-size:10px}.aw-gis-detail dd{font-size:24px;margin:4px 0}.aw-gis-detail em{font-size:10px;font-style:normal;color:#7297a3}.aw-gis-offline{position:absolute;bottom:50px;left:20px;background:#101f2be8;color:#ebc891;padding:10px 14px;z-index:405;font-size:12px}.aw-gis-offline button{border:0;background:none;color:#6ce5c0;cursor:pointer;margin-left:12px}
</style>

<style>.aw-gis-marker-host{background:transparent;border:0}.aw-gis-marker{width:16px;height:16px;border:2px solid #d5fff0;border-radius:50%;background:var(--marker-color);box-shadow:0 0 0 5px #61e8c924,0 0 15px #61e8c94d;cursor:pointer;padding:0}.aw-gis-marker:focus-visible{outline:2px solid white;outline-offset:5px}</style>
